#!/usr/bin/env bash
# ABOUTME: Strips the "Generated by Claude Code" footer from every recent dravr-carnet issue body and comment
# ABOUTME: Run by carnet-strip-footer.yml; the footer is appended after the body leaves the session, so only a sweep removes it
#
# SPDX-License-Identifier: MIT OR Apache-2.0
# Copyright (c) 2026 dravr.ai
#
# A Claude Code on the web session posts every GitHub write through its proxy,
# and the stored body comes back ending in `---` + `_Generated by [Claude
# Code](https://claude.ai/code)_`. carnet.sh strips that footer before it posts
# (its UNSIGNED filter), yet 672 bodies carried it by 2026-10-20 — claim
# markers built entirely by the script among them — so it is added after the
# body leaves the session. No setting reaches it: `attribution` covers only
# commits and pull requests, and a multi-repo cloud session reads no
# settings.json. The footer says nothing (every entry is written by a Claude
# session) and is paid for on every later read, so this edits it back out.
#
# Inside a carnet marker the footer sits in the JSON `reason` string, escaped
# as `\n\n---\n_Generated…_`; the filter takes the escaped form too, so the
# marker stays valid JSON.
#
#   strip-carnet-footer.sh [--dry-run] [--since <ISO-8601>]
#
# Reads entries updated since --since (default: 3 hours ago, so an hourly run
# overlaps the previous one). GH_TOKEN must reach the private tracker; an empty
# token fails rather than sweeping nothing. dravr-carnet is private and this
# lane runs in a public repository, so only counts are printed, never a body.
# Exits 1 when an edit fails or the stored body still carries the footer.
set -euo pipefail

REPO="${CARNET_REPO:-dravr-ai/dravr-carnet}"
DRY_RUN=false
SINCE=""

while [ $# -gt 0 ]; do
    case "$1" in
        --dry-run) DRY_RUN=true ;;
        --since) SINCE="${2:?--since needs an ISO-8601 timestamp}"; shift ;;
        *) echo "unknown argument: $1" >&2; exit 2 ;;
    esac
    shift
done

if [ -z "${GH_TOKEN:-}" ]; then
    echo "GH_TOKEN is empty: it must reach $REPO, or the sweep would read nothing and pass" >&2
    exit 1
fi

if [ -z "$SINCE" ]; then
    SINCE=$(date -u -d '3 hours ago' +%Y-%m-%dT%H:%M:%SZ 2>/dev/null \
        || date -u -v-3H +%Y-%m-%dT%H:%M:%SZ)
fi

# The footer with its leading `---` rule and the blank lines around it, literal
# or JSON-escaped, in either wording Claude Code has used.
STRIP='def footer: "(\\s|\\\\n)*(-{3,})?(\\s|\\\\n)*_?(🤖\\s*)?Generated (by|with) \\[Claude Code\\]\\(https://claude\\.(ai|com)/(code|claude-code)\\)_?";
def strip: gsub(footer; "") | sub("\\s*$"; "\n");
def signed: test(footer);'

WORK=$(mktemp -d)
trap 'rm -rf "$WORK"' EXIT

# One line per entry to edit: <endpoint> <payload file>.
gh api --paginate "repos/$REPO/issues/comments?since=$SINCE&per_page=100" \
    | jq -c "$STRIP"'.[] | select(.body // "" | signed) | {path: "issues/comments/\(.id)", body: (.body | strip)}' \
    > "$WORK/comments"
gh api --paginate "repos/$REPO/issues?state=all&since=$SINCE&per_page=100" \
    | jq -c "$STRIP"'.[] | select(.body // "" | signed) | {path: "issues/\(.number)", body: (.body | strip)}' \
    > "$WORK/issues"

found=$(cat "$WORK/comments" "$WORK/issues" | wc -l | tr -d ' ')
edited=0
failed=0
n=0
while IFS= read -r row; do
    n=$((n + 1))
    if [ "$DRY_RUN" = true ]; then
        continue
    fi
    jq '{body}' <<<"$row" > "$WORK/payload.$n"
    path=$(jq -r .path <<<"$row")
    if ! stored=$(gh api -X PATCH "repos/$REPO/$path" --input "$WORK/payload.$n"); then
        failed=$((failed + 1))
        continue
    fi
    if jq -e "$STRIP"'.body // "" | signed' <<<"$stored" >/dev/null; then
        echo "an edited entry still carries the footer: the write path re-appends it" >&2
        failed=$((failed + 1))
        continue
    fi
    edited=$((edited + 1))
done < <(cat "$WORK/comments" "$WORK/issues")

mode=""
[ "$DRY_RUN" = true ] && mode=" (dry run: nothing edited)"
echo "since $SINCE: $found entries carried the footer, $edited edited, $failed failed$mode"
[ "$failed" -eq 0 ]
